/**
 * 负责噩梦之影原名单、生命绑定、夜窗口与恐惧效果授权；输入为原角色与已通过目标政策的选择。
 * 输出是当前恐惧／狼刀阻断查询和原提交结果；仅原名单参与，组件替换不能悄然重开夜。
 * 数据构造、校验、写入和身份编码归同族状态槽；本 frame 保留 expectedState 更新和夜字段提交顺序。
 * 失败保留已写前缀，不以玩家投影或恐惧文案替代原生命／能力复验，也不回滚历史或补做关闭。
 * 当前 Camp 在原字段点由实际 World 查询；保原值比较，不把同值组件替换改成新的引用撤权。
 */
import type {
  NightmareShadowReadState,
} from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../core/domain/components/names";
import {
  aliveLifeVersion,
  aliveLifeDescriptor,
  type AliveComponent,
} from "../../../../core/domain/components/alive";

import type { World } from "../../../../core/domain/world";
import { Camp, type EntityId } from "../../../../core/domain/identity";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import type { NightAbilityReadView } from "../abilities";
import { getNightmareShadowState, NIGHTMARE_SHADOW_STATE_SLOT } from "./state-slot";
import { nightmareFearTargets } from "./targets";

function authority(ability: NightAbilityReadView): string {
  const state = ability.state as unknown as Record<string, unknown>;
  return JSON.stringify([
    ability.id,
    ability.kind,
    ability.activation,
    ability.source,
    ability.sourceDisclosed,
    ability.startsOnDay,
    ability.expiresAfterDay,
    ability.maxUses,
    ability.disabled,
    ability.deathExpired,
    state.targetPolicy,
    state.actionPolicy,
    state.selfHealRule,
    state.knifeVisibility,
    state.potionPolicy,
    state.repeatPolicy,
    state.policy,
    state.inspectionPolicy,
    state.protectionPolicy,
  ]);
}
function captureRole(world: World, id: EntityId) {
  const role = world.getComponent(id, COMPONENT.Role);
  if (!role) throw new Error("nightmare_roster_missing");
  const kind = role.role,
    camp = world.getComponent(id, COMPONENT.Camp)?.camp,
    privateState = role.privateState;
  const life = world.getComponent(id, COMPONENT.Alive);
  const descriptor = life && aliveLifeDescriptor(life);
  const version = life && aliveLifeVersion(life);
  if (!life || !descriptor || version === undefined)
    throw new Error("nightmare_roster_life_missing");
  const lifeCurrent = () => {
    const current = Object.getOwnPropertyDescriptor(life, "alive");
    return (
      world.getComponent(id, COMPONENT.Alive) === life &&
      current?.get === descriptor.get &&
      current?.set === descriptor.set &&
      (aliveLifeVersion(life) === version ||
        (aliveLifeVersion(life) === version + 1 && !life.alive))
    );
  };
  const refs = Object.entries(privateState);
  const slots = Object.entries((privateState as { readonly abilities?: unknown }).abilities ?? {});
  const abilities = Object.values(
    ((privateState as { readonly abilities?: unknown }).abilities ?? {}) as Record<
      string,
      NightAbilityReadView
    >,
  ).map((ability) => ({
    ability,
    state: ability.state,
    source: ability.source,
    identity: authority(ability),
  }));
  return {
    id,
    role,
    current: () =>
      lifeCurrent() &&
      world.getComponent(id, COMPONENT.Role) === role &&
      role.role === kind &&
      world.getComponent(id, COMPONENT.Camp)?.camp === camp &&
      role.privateState === privateState &&
      refs.every(
        ([key, value]) => (privateState as Readonly<Record<string, unknown>>)[key] === value,
      ) &&
      Object.keys((privateState as { readonly abilities?: unknown }).abilities ?? {}).length ===
        slots.length &&
      slots.every(
        ([key, value]) =>
          (
            (privateState as { readonly abilities?: unknown }).abilities as
              Record<string, unknown> | undefined
          )?.[key] === value,
      ) &&
      abilities.every(
        (a) =>
          a.ability.state === a.state &&
          a.ability.source === a.source &&
          authority(a.ability) === a.identity,
      ),
  };
}
type Board = {
  actorId: EntityId;
  state: NightmareShadowReadState;
  expectedState: string;
  roster: ReturnType<typeof captureRole>[];
  night: {
    day: number;
    required: boolean;
    committed: boolean;
    target: NightLifeScope | null;
    wolfBlocked: boolean;
  } | null;
};
const boards = new WeakMap<World, Board>();
export function installNightmareBoard(world: World): void {
  if (boards.has(world)) throw new Error("nightmare_board_reinstall");
  const roster = world.entityIds().map((id) => captureRole(world, id));
  const actors = roster.filter((row) => getNightmareShadowState(row.role, () => world.getComponent(row.id, COMPONENT.Camp)));
  if (actors.length !== 1) throw new Error("nightmare_actor_count");
  const state = getNightmareShadowState(actors[0].role, () => world.getComponent(actors[0].id, COMPONENT.Camp))!;
  boards.set(world, {
    actorId: actors[0].id,
    state,
    expectedState: NIGHTMARE_SHADOW_STATE_SLOT.checkpoint.identity(state),
    roster,
    night: null,
  });
}
export function isNightmareBoard(world: World): boolean {
  return boards.has(world);
}
export function assertNightmareRosterCurrent(world: World): void {
  const board = boards.get(world);
  if (!board) return;
  if (
    world.entityIds().length !== board.roster.length ||
    board.roster.some((row) => !row.current()) ||
    getNightmareShadowState(world.getComponent(board.actorId, COMPONENT.Role), () => world.getComponent(board.actorId, COMPONENT.Camp)) !== board.state ||
    NIGHTMARE_SHADOW_STATE_SLOT.checkpoint.identity(board.state) !== board.expectedState
  )
    throw new Error("nightmare_roster_revoked");
}
export function beginNightmareNight(world: World, day: number): EntityId | null {
  const board = boards.get(world);
  if (!board) return null;
  assertNightmareRosterCurrent(world);
  if (
    !Number.isSafeInteger(day) ||
    day !== (board.night?.day ?? 0) + 1 ||
    (board.night?.required && !board.night.committed)
  )
    throw new Error("nightmare_night_reentry");
  board.night = {
    day,
    required: world.getAliveEntityIds().includes(board.actorId),
    committed: false,
    target: null,
    wolfBlocked: false,
  };
  return world.getAliveEntityIds().includes(board.actorId) ? board.actorId : null;
}
export function nightmarePackReady(world: World): boolean {
  assertNightmareRosterCurrent(world);
  return boards.get(world)?.state.packReady ?? true;
}
export function commitNightmareFear(
  world: World,
  actorId: EntityId,
  day: number,
  targetId: EntityId | null,
): void {
  assertNightmareRosterCurrent(world);
  const board = boards.get(world),
    night = board?.night;
  if (
    !board ||
    !night ||
    board.actorId !== actorId ||
    night.day !== day ||
    night.committed ||
    !world.getAliveEntityIds().includes(actorId)
  )
    throw new Error("nightmare_fear_scope_invalid");
  const candidates = nightmareFearTargets(world, actorId, day);
  if (
    targetId === null
      ? board.state.fearActionPolicy === "required_when_legal" && candidates.length > 0
      : !candidates.includes(targetId)
  )
    throw new Error("nightmare_fear_target_invalid");
  const target = targetId === null ? null : captureNightLife(world, targetId);
  if (targetId !== null && !target) throw new Error("nightmare_fear_target_invalid");
  const wolfBlocked =
    targetId !== null && world.getComponent(targetId, COMPONENT.Camp)?.camp === Camp.Wolf;
  NIGHTMARE_SHADOW_STATE_SLOT.allowedWrites.recordFear(() => board.state, day, targetId);
  board.expectedState = NIGHTMARE_SHADOW_STATE_SLOT.checkpoint.identity(board.state);
  night.committed = true;
  night.target = target;
  night.wolfBlocked = wolfBlocked;
}
/** 原正常首次死亡仍保留本夜禁言供死亡行动窗口使用；复活或生命替换不因此获得续权。 */
export function nightmareFearBlocks(
  world: World,
  id: EntityId,
  day: number,
  allowFirstDeath = false,
): boolean {
  assertNightmareRosterCurrent(world);
  const night = boards.get(world)?.night,
    target = night?.target;
  if (!night || night.day !== day || !target || target.id !== id) return false;
  if (livingNightLife(world, target)) return true;
  if (!allowFirstDeath) throw new Error("nightmare_target_life_revoked");
  return (
    world.getComponent(id, COMPONENT.Alive) === target.life &&
    !target.life.alive &&
    aliveLifeVersion(target.life) === target.version + 1
  );
}
export function nightmareKnifeBlocked(world: World, day?: number): boolean {
  assertNightmareRosterCurrent(world);
  const night = boards.get(world)?.night;
  return !!night && (day === undefined || night.day === day) && night.wolfBlocked;
}

export function nightmareFearPending(world: World, actorId: EntityId, day: number): boolean {
  assertNightmareRosterCurrent(world);
  const board = boards.get(world),
    night = board?.night;
  return (
    !!board &&
    !!night &&
    board.actorId === actorId &&
    night.day === day &&
    night.required &&
    !night.committed &&
    world.getAliveEntityIds().includes(actorId)
  );
}

/**
 * 负责魔术师唯一状态槽的创建、完整 live 校验、同引用读取、初始化／历史写入与原身份编码。
 * 输入为原角色、参数及晚读容器，输出为原状态引用、脱离知识副本或原明确拒绝；原完整字段、
 * descriptor、日次、排序及一次性号码校验不变。写权仅收走原赋值与历史追加，失败保留已写前缀。
 * frame 仍拥有原体生命、夜窗口、交换关系及 expectedState 检查点；此槽不另建立 shadow、
 * 退款、标死、关闭、付新资源或授予请求许可。身份 JSON 仅为原运行比对，档案 schema／核验仍归原 owner。
 * 角色阵营渠道已退出；reader／project 以显式晚读 CurrentCampSource 获取实际 Camp，原 raw schema／写者不因此获得许可。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import type {
  MagicianChoice,
  MagicianState,
  MagicianReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { Camp, type RoleComponent } from "../../../../core";
export const MAGICIAN_ROLE = "magician" as const;
export const MAGICIAN_POLICY = "awa_magician_wolf_king_v1" as const;
function field(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function exact(value: unknown, keys: readonly string[]): boolean {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === keys.length &&
    keys.every((k) => descriptors[k] && "value" in descriptors[k]!)
  );
}
function integer(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function arrayItems(value: unknown): unknown[] | null {
  if (types.isProxy(value) || !Array.isArray(value)) return null;
  const length = field(value, "length");
  if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0) return null;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).length !== length + 1) return null;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const d = descriptors[String(i)];
    if (!d || !("value" in d)) return null;
    result.push(d.value);
  }
  return result;
}
/** 完整原 live 校验：仅读自身数据 descriptor，先拒绝 Proxy；不调用 caller getter、迭代器或数组方法。
 * 合法时返回原状态及历史引用，不克隆／冻结；readonly 是读方类型，不能替代 frame 原授权。 */
// 当前阵营只在原 camp 数据读取点取得；保本族自身 descriptor／Proxy 策略，不回退角色或目录。
export function getMagicianState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): MagicianReadState | undefined {
  if (field(role, "role") !== MAGICIAN_ROLE || field(currentCamp(), "camp") !== Camp.Good) return undefined;
  const state = field(field(role, "privateState"), "magician");
  if (!exact(state, ["policy", "firstNight", "deathShotTargetPolicy", "history"])) return undefined;
  const firstNight = field(state, "firstNight");
  if (field(state, "policy") !== MAGICIAN_POLICY || (firstNight !== 1 && firstNight !== 2))
    return undefined;
  const shot = field(state, "deathShotTargetPolicy");
  if (shot !== "original" && shot !== "exchanged") return undefined;
  const history = arrayItems(field(state, "history"));
  if (!history) return undefined;
  // 历史日期严格递增；非空二人组保持原升序／全局号码一次使用，null 不消耗号码。
  let previous = 0;
  const used = new Set<number>();
  for (const entry of history) {
    if (!exact(entry, ["day", "pair"])) return undefined;
    const day = field(entry, "day"),
      rawPair = field(entry, "pair");
    if (!integer(day) || day < firstNight || day <= previous) return undefined;
    previous = day;
    if (rawPair === null) continue;
    const pair = arrayItems(rawPair);
    if (
      !pair ||
      pair.length !== 2 ||
      !integer(pair[0]) ||
      !integer(pair[1]) ||
      pair[0] >= pair[1] ||
      used.has(pair[0]) ||
      used.has(pair[1])
    )
      return undefined;
    used.add(pair[0]);
    used.add(pair[1]);
  }
  return state as MagicianReadState;
}
export function createMagicianState(
  firstNight: 1 | 2,
  deathShotTargetPolicy: "original" | "exchanged" = "original",
): MagicianState {
  return { policy: MAGICIAN_POLICY, firstNight, deathShotTargetPolicy, history: [] };
}
/** 按原 descriptor 逐行复制知识，嵌套二人组脱离；不使用 caller 数组 species 或解码为运行许可。 */
export function projectMagicianState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): MagicianState | undefined {
  const state = getMagicianState(role, currentCamp);
  if (!state) return undefined;
  const history: MagicianChoice[] = [];
  for (const row of arrayItems(field(state, "history"))!) {
    const rawPair = field(row, "pair");
    const values = rawPair === null ? null : arrayItems(rawPair)!;
    history.push({
      day: field(row, "day") as number,
      pair: values ? [values[0] as number, values[1] as number] : null,
    });
  }
  return {
    policy: MAGICIAN_POLICY,
    firstNight: field(state, "firstNight") as 1 | 2,
    deathShotTargetPolicy: field(state, "deathShotTargetPolicy") as "original" | "exchanged",
    history,
  };
}

/** 初始化只有原左值赋值：容器先于 create 的参数读取，setter 或创建失败不补写或回滚。 */
function installMagicianState(
  privateState: () => Record<string, unknown>,
  value: { firstNight: 1 | 2; deathShotTargetPolicy: "original" | "exchanged" },
): void {
  privateState().magician = createMagicianState(
    value.firstNight,
    value.deathShotTargetPolicy,
  );
}

/** 原准入仍由 frame 完成；先取 defineProperty，再两次晚读原状态，保 index／descriptor 写入顺序。 */
function appendMagicianHistory(
  state: () => MagicianReadState,
  day: number,
  chosen: [number, number] | null,
): void {
  Object.defineProperty(state().history, String(state().history.length), {
    value: { day, pair: chosen },
    writable: true,
    enumerable: true,
    configurable: true,
  });
}

/** 原 frame 的身份编码，不是严格档案 codec；先 project／拒绝，再找 JSON.stringify 并编码原副本。 */
function encodeMagicianStateIdentity(
  role: RoleComponent,
  currentCamp: CurrentCampSource,
): string {
  const view = projectMagicianState(role, currentCamp);
  if (!view) throw new Error("magician_original_state_revoked");
  return JSON.stringify(view);
}

/**
 * 本族唯一数据槽贡献：schema 与 get 是同一完整 live 校验，不另造更严格接受政策。
 * allowedWrites 保原初始化和历史 descriptor 写；frame 的 expectedState、pair、committed
 * 仍在原顺序更新。checkpoint 只提供原 JSON 身份编码，不存第二份状态或解析玩家许可。
 * 冻结的是贡献方法表，不冻结输入状态、历史或投影；录制仍完整克隆原 privateState。
 */
export const MAGICIAN_STATE_SLOT = Object.freeze({
  create: createMagicianState,
  schema: getMagicianState,
  get: getMagicianState,
  project: projectMagicianState,
  install: installMagicianState,
  allowedWrites: Object.freeze({ appendHistory: appendMagicianHistory }),
  checkpoint: Object.freeze({ identity: encodeMagicianStateIdentity }),
});

/**
 * 负责诡术师唯一状态槽的创建、完整 live 校验、同引用读取、脱离选择／知识副本及原实际写入。
 * 输入为原角色、日期、合法号码和晚读容器；输出保持原状态、副本和明确拒绝顺序。
 * 原 history 递增／相邻夜不能连续跳过／号码一次使用规则保留；失败不修复已写前缀或退还号码。
 * frame 仍唯一拥有原体生命、夜窗口、finished／exileResolved、映射与 expectedState。
 * 本槽不另建状态镜像，不授行动许可或结算放逐；身份 JSON 仅为运行比对，非档案 decoder。
 * 角色阵营渠道已退出；reader／project 以显式晚读 CurrentCampSource 获取实际 Camp，原 raw schema／写者不因此获得许可。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import type {
  TricksterChoice,
  TricksterState,
  TricksterReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { Camp, type RoleComponent } from "../../../../core";
export const TRICKSTER_ROLE = "trickster" as const;
export const TRICKSTER_POLICY = "awa_trickster_exile_v1" as const;
function field(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function exact(value: unknown, keys: readonly string[]): boolean {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === keys.length &&
    keys.every((k) => descriptors[k] && "value" in descriptors[k]!)
  );
}
function integer(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function arrayItems(value: unknown): unknown[] | null {
  if (types.isProxy(value) || !Array.isArray(value)) return null;
  const length = field(value, "length");
  if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0) return null;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).length !== length + 1) return null;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const d = descriptors[String(i)];
    if (!d || !("value" in d)) return null;
    result.push(d.value);
  }
  return result;
}
/** 完整原校验先拒绝 Proxy，再仅读自身 data descriptor，不执行输入 getter、迭代器或数组方法。
 * 合法 live 读返回原状态／history 引用；readonly 是读方类型，不提供写许可或原体生命保证。 */
// 当前阵营只在原 camp 数据读取点取得；保本族自身 descriptor／Proxy 策略，不回退角色或目录。
export function getTricksterState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): TricksterReadState | undefined {
  if (field(role, "role") !== TRICKSTER_ROLE || field(currentCamp(), "camp") !== Camp.Wolf) return undefined;
  const state = field(field(role, "privateState"), "trickster");
  if (!exact(state, ["policy", "history"])) return undefined;
  if (field(state, "policy") !== TRICKSTER_POLICY) return undefined;
  const history = arrayItems(field(state, "history"));
  if (!history) return undefined;
  // null 不消费号码，但相邻两夜的 null 历史仍被拒绝；跨日间隔不扩成连续跳过。
  let previous = 0;
  let previousPass = false;
  const used = new Set<number>();
  for (const entry of history) {
    if (!exact(entry, ["day", "pair"])) return undefined;
    const day = field(entry, "day"),
      rawPair = field(entry, "pair");
    if (!integer(day) || day <= previous) return undefined;
    if (rawPair === null && previousPass && day === previous + 1) return undefined;
    previous = day;
    previousPass = rawPair === null;
    if (rawPair === null) continue;
    const pair = arrayItems(rawPair);
    if (
      !pair ||
      pair.length !== 2 ||
      !integer(pair[0]) ||
      !integer(pair[1]) ||
      pair[0] >= pair[1] ||
      used.has(pair[0]) ||
      used.has(pair[1])
    )
      return undefined;
    used.add(pair[0]);
    used.add(pair[1]);
  }
  return state as TricksterReadState;
}
export function createTricksterState(): TricksterState {
  return { policy: TRICKSTER_POLICY, history: [] };
}
/** 仅复制历史及非空 pair；原可写知识副本不含 frame 句柄或夜／放逐许可。 */
export function projectTricksterState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): TricksterState | undefined {
  const state = getTricksterState(role, currentCamp);
  if (!state) return undefined;
  const history: TricksterChoice[] = [];
  for (const row of arrayItems(field(state, "history"))!) {
    const rawPair = field(row, "pair");
    const values = rawPair === null ? null : arrayItems(rawPair)!;
    history.push({
      day: field(row, "day") as number,
      pair: values ? [values[0] as number, values[1] as number] : null,
    });
  }
  return {
    policy: TRICKSTER_POLICY,
    history,
  };
}

/** 返回脱离的下一选择，不改原 history；原 day／连续跳过／legalIds 政策保留，准入仍由 frame 复验。 */
export function nextTricksterChoice(
  role: RoleComponent | undefined,
  day: number,
  pair: readonly [number, number] | null,
  legalIds: readonly number[],
  currentCamp: CurrentCampSource,
): TricksterState {
  const state = projectTricksterState(role, currentCamp);
